B.api=new A.bL([0,"\u0915\u093e\u092e\u0941\u0915\u0903 \u0938\u094d\u0924\u094d\u0930\u0940\u0935\u0936\u094b \u0927\u0928\u0928\u093e\u0936\u094b \u092e\u0947\u0937\u0947 \u0936\u0941\u0915\u094d\u0930\u0947",1,"\u0938\u0941\u0916\u0940 \u0927\u0928\u0935\u093e\u0928\u094d \u0938\u0941\u0928\u094d\u0926\u0930\u092a\u0924\u094d\u0928\u0940 \u0935\u0943\u0937\u092d\u0947 \u0936\u0941\u0915\u094d\u0930\u0947",2,"\u0915\u0932\u093e\u0915\u093e\u0930\u094b \u0935\u093f\u0926\u094d\u0935\u093e\u0928\u094d \u092e\u093f\u0925\u0941\u0928\u0947 \u092d\u093e\u0930\u094d\u0917\u0935\u0947",3,"\u0917\u0943\u0939\u0938\u0941\u0916\u0902 \u0935\u093e\u0939\u0928\u0902 \u092e\u093f\u0924\u094d\u0930\u0902 \u0915\u0930\u094d\u0915\u091f\u0947 \u0936\u0941\u0915\u094d\u0930\u0947",4,"\u0936\u0924\u094d\u0930\u0941\u0903 \u092e\u093e\u0928\u0939\u093e\u0928\u093f\u0903 \u0938\u093f\u0902\u0939\u0947 \u0936\u0941\u0915\u094d\u0930\u0947",5,"\u0936\u0924\u094d\u0930\u0941\u091c\u092f\u0940 \u0927\u0928\u0932\u093e\u092d\u0903 \u0915\u0928\u094d\u092f\u093e\u092f\u093e\u0902 \u092d\u093e\u0930\u094d\u0917\u0935\u0947",6,"\u0938\u0941\u0916\u0940 \u0930\u093e\u091c\u0938\u092e\u094d\u092e\u093e\u0928\u0903 \u0915\u0932\u093e\u092a\u094d\u0930\u093f\u092f\u094b \u0924\u0941\u0932\u093e\u092f\u093e\u0902 \u0936\u0941\u0915\u094d\u0930\u0947",7,"\u092e\u093e\u0928\u0939\u093e\u0928\u093f\u0930\u094d\u0930\u094b\u0917\u0903 \u0915\u0932\u0939\u094b \u0935\u0943\u0936\u094d\u091a\u093f\u0915\u0947 \u0936\u0941\u0915\u094d\u0930\u0947",8,"\u0927\u0928\u0902 \u0938\u094d\u0924\u094d\u0930\u0940\u0938\u0941\u0916\u0902 \u0935\u093e\u0939\u0928\u0902 \u0927\u0928\u0941\u0937\u093f \u092d\u093e\u0930\u094d\u0917\u0935\u0947",9,"\u0927\u0928\u0928\u093e\u0936\u0903 \u0938\u094d\u0924\u094d\u0930\u0940\u0915\u0937\u094d\u091f\u0902 \u092e\u0915\u0930\u0947 \u0936\u0941\u0915\u094d\u0930\u0947",10,"\u0915\u093e\u092e\u0941\u0915\u0903 \u092a\u0930\u0938\u094d\u0924\u094d\u0930\u0940\u0938\u0919\u094d\u0917\u0940 \u0915\u0941\u092e\u094d\u092d\u0947 \u0936\u0941\u0915\u094d\u0930\u0947",11,"\u0927\u0928\u0938\u0941\u0916\u0938\u0919\u094d\u0917\u0940\u0924\u092a\u094d\u0930\u0940\u0924\u093f\u0903 \u092e\u0940\u0928\u0947 \u092d\u093e\u0930\u094d\u0917\u0935\u0947"],t.TM)
B.apq=new A.bL([0,"\u0905\u091f\u0928\u0936\u0940\u0932\u0903 \u0915\u094d\u0930\u0942\u0930\u094b \u0930\u094b\u0917\u0940 \u092e\u0947\u0937\u0947 \u0936\u0928\u094c",1,"\u0915\u0943\u0937\u093f\u0915\u093e\u0930\u0903 \u0938\u0947\u0935\u0915\u094b \u092e\u0928\u094d\u0926\u094b \u0935\u0943\u0937\u092d\u0947 \u0936\u0928\u094c",2,"\u092e\u0947\u0927\u093e\u0935\u0940 \u0926\u0941\u0903\u0938\u0919\u094d\u0917\u0940 \u092e\u093f\u0925\u0941\u0928\u0947 \u092e\u0928\u094d\u0926\u0947",3,"\u0926\u0930\u093f\u0926\u094d\u0930\u094b \u0926\u0941\u0903\u0916\u0940 \u091a\u093f\u0928\u094d\u0924\u093e\u0915\u0941\u0932\u094b \u0915\u0930\u094d\u0915\u091f\u0947 \u0936\u0928\u094c",4,"\u0936\u0924\u094d\u0930\u0941\u0935\u093e\u0928\u094d \u0935\u0928\u0935\u093e\u0938\u0940 \u0915\u094d\u0930\u0942\u0930\u094b \u0938\u093f\u0902\u0939\u0947 \u0936\u0928\u094c",5,"\u0930\u094b\u0917\u0940 \u0905\u091f\u0928\u0936\u0940\u0932\u0903 \u0938\u0947\u0935\u0915\u0903 \u0915\u0928\u094d\u092f\u093e\u092f\u093e\u0902 \u092e\u0928\u094d\u0926\u0947",6,"\u0927\u0928\u0935\u093f\u0926\u094d\u092f\u093e\u0935\u093e\u0928\u094d \u0935\u0923\u093f\u0915\u094d \u0924\u0941\u0932\u093e\u092f\u093e\u0902 \u0936\u0928\u094c",7,"\u092c\u0928\u094d\u0927\u0928\u0902 \u092e\u093e\u0928\u0939\u093e\u0928\u093f\u0930\u094d\u0930\u094b\u0917\u094b \u0935\u0943\u0936\u094d\u091a\u093f\u0915\u0947 \u0936\u0928\u094c",8,"\u0927\u0948\u0930\u094d\u092f\u0935\u093e\u0928\u094d \u0938\u093e\u0939\u0938\u0940 \u092f\u093e\u0924\u094d\u0930\u093e\u092a\u094d\u0930\u093f\u092f\u094b \u0927\u0928\u0941\u0937\u093f \u092e\u0928\u094d\u0926\u0947",9,"\u0927\u0930\u094d\u092e\u0928\u093f\u0937\u094d\u0920\u0903 \u0915\u093e\u0930\u094d\u092f\u0938\u093f\u0926\u094d\u0927\u093f\u0903 \u092e\u0915\u0930\u0947 \u0936\u0928\u094c",10,"\u0928\u0940\u091a\u0915\u0930\u094d\u092e\u093e \u091a\u094c\u0930\u094d\u092f\u0902 \u092e\u0943\u0937\u093e\u0935\u093e\u0926\u0940 \u0915\u0941\u092e\u094d\u092d\u0947 \u0936\u0928\u094c",11,"\u0938\u0947\u0935\u0915\u0903 \u0915\u0937\u094d\u091f\u0915\u093e\u0930\u0940 \u0930\u094b\u0917\u0940 \u092e\u0940\u0928\u0947 \u092e\u0928\u094d\u0926\u0947"],t.TM)
